#!/usr/bin/env python3
"""Static invariant probe for the CVE-2022-29581 cls_u32 port.

Run from a checkout whose net/sched/cls_u32.c has the candidate patch applied.
Exits 0 only if the intended security invariant holds textually.
This is a static assertion, NOT a build or runtime test.
"""
import sys

path = sys.argv[1] if len(sys.argv) > 1 else "net/sched/cls_u32.c"
src = open(path, encoding="utf-8", errors="replace").read()

errors = []

# 1. helper exists
if "static void __u32_destroy_key(struct tc_u_knode *n)" not in src:
    errors.append("missing __u32_destroy_key helper")

# 2. helper body must not put the netns
start = src.find("static void __u32_destroy_key")
end = src.find("static void u32_destroy_key", start + 1)
if start == -1 or end == -1:
    errors.append("cannot delimit helper/wrapper")
else:
    helper = src[start:end]
    if "tcf_exts_put_net" in helper:
        errors.append("__u32_destroy_key must not call tcf_exts_put_net")
    if "kfree(n)" not in helper:
        errors.append("__u32_destroy_key must kfree(n)")

# 3. wrapper still releases the netns for the normal (get_net) callers
wstart = src.find("static void u32_destroy_key")
wend = src.find("/* u32_delete_key_rcu", wstart + 1)
if wstart == -1 or wend == -1:
    errors.append("cannot delimit wrapper")
else:
    wrapper = src[wstart:wend]
    if "tcf_exts_put_net(&n->exts);" not in wrapper:
        errors.append("u32_destroy_key wrapper lost tcf_exts_put_net")
    if "__u32_destroy_key(n);" not in wrapper:
        errors.append("u32_destroy_key wrapper must delegate to __u32_destroy_key")

# 4. both vulnerable error paths redirected
if src.count("__u32_destroy_key(new)") != 2:
    errors.append("expected exactly 2 __u32_destroy_key(new) error-path calls, found %d"
                  % src.count("__u32_destroy_key(new)"))
if "u32_destroy_key(tp, new, false)" in src:
    errors.append("vulnerable u32_destroy_key(tp, new, false) call remains")

# 5. normal destroy call paths preserved
for caller in ("u32_destroy_key(key->tp, key, false);",
               "u32_destroy_key(key->tp, key, true);",
               "u32_destroy_key(n->tp, n, true);"):
    if caller not in src:
        errors.append("normal destroy caller missing: " + caller)

if errors:
    print("INVARIANT PROBE FAILED")
    for e in errors:
        print(" - " + e)
    sys.exit(1)
print("INVARIANT PROBE PASSED: helper has no put_net; wrapper keeps put_net; "
      "both error paths use __u32_destroy_key(new); normal callers intact")

